import { CLOSED_ISSUE_STATUSES } from "@/types/issue";
import type { Issue } from "@/types/issue";

/** Raised when a parent placement would loop the tree or nest it too deeply. */
export class IssueHierarchyError extends Error {
  readonly code = "conflict" as const;

  constructor(
    readonly issueId: string,
    readonly reason: "cycle" | "too_deep",
  ) {
    super(
      reason === "cycle"
        ? `Issue ${issueId} cannot be placed under itself or one of its sub-issues.`
        : `Placing issue ${issueId} there would nest sub-issues too deeply.`,
    );
    this.name = "IssueHierarchyError";
  }
}

/** Read-only view of a project's issue tree, built from every row (archived included). */
export interface IssueTree {
  readonly byId: ReadonlyMap<string, Issue>;
  readonly childrenOf: ReadonlyMap<string, readonly Issue[]>;
}

export function buildIssueTree(issues: readonly Issue[]): IssueTree {
  const byId = new Map<string, Issue>();
  const childrenOf = new Map<string, Issue[]>();
  for (const issue of issues) {
    byId.set(issue.id, issue);
    if (issue.parentId === null) continue;
    const bucket = childrenOf.get(issue.parentId) ?? [];
    bucket.push(issue);
    childrenOf.set(issue.parentId, bucket);
  }
  return { byId, childrenOf };
}

/** Every issue below `issueId` at any depth, breadth first, loop-safe. */
export function descendantsOf(tree: IssueTree, issueId: string): readonly Issue[] {
  const seen = new Set<string>([issueId]);
  const result: Issue[] = [];
  let frontier = [issueId];
  while (frontier.length > 0) {
    const next: string[] = [];
    for (const id of frontier) {
      for (const child of tree.childrenOf.get(id) ?? []) {
        if (seen.has(child.id)) continue;
        seen.add(child.id);
        result.push(child);
        next.push(child.id);
      }
    }
    frontier = next;
  }
  return result;
}

/** Level of an issue: a root is 0. */
export function depthOf(tree: IssueTree, issueId: string): number {
  const seen = new Set<string>([issueId]);
  let depth = 0;
  let current = tree.byId.get(issueId);
  while (current?.parentId != null && !seen.has(current.parentId)) {
    seen.add(current.parentId);
    depth += 1;
    current = tree.byId.get(current.parentId);
  }
  return depth;
}

/** Levels between an issue and its deepest descendant (0 for a leaf). */
export function heightOf(tree: IssueTree, issueId: string): number {
  const seen = new Set<string>([issueId]);
  let frontier = [issueId];
  let height = 0;
  while (true) {
    const next: string[] = [];
    for (const id of frontier) {
      for (const child of tree.childrenOf.get(id) ?? []) {
        if (seen.has(child.id)) continue;
        seen.add(child.id);
        next.push(child.id);
      }
    }
    if (next.length === 0) return height;
    height += 1;
    frontier = next;
  }
}

export function isClosedStatus(status: Issue["status"]): boolean {
  return CLOSED_ISSUE_STATUSES.includes(status);
}
