/** Loads a parent candidate: it must exist in the project and be live. */
async function requireLiveParent(
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null || parent.projectId !== projectId) {
    throw new NotFoundError("Issue", parentId);
  }
  assertNotArchived("Issue", parent.id, parent);
  return parent;
}

/**
 * Places an issue under a parent of its own project, moves it, or makes it a
 * root again (`parentId: null`). Its sub-issues travel with it, so the depth
 * check looks at where its deepest descendant would land.
 */
export async function setIssueParent(
  actor: Actor,
  input: SetIssueParentInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  if (input.parentId !== null) {
    const parent = await requireLiveParent(
      input.orgId,
      issue.projectId,
      input.parentId,
    );
    const tree = buildIssueTree(
      await issueRepo.listProjectIssues(input.orgId, issue.projectId),
    );
    if (
      parent.id === issue.id ||
      descendantsOf(tree, issue.id).some((d) => d.id === parent.id)
    ) {
      throw new IssueHierarchyError(issue.id, "cycle");
    }
    if (
      depthOf(tree, parent.id) + 1 + heightOf(tree, issue.id) >
      MAX_SUB_ISSUE_DEPTH
    ) {
      throw new IssueHierarchyError(issue.id, "too_deep");
    }
  }

  if (issue.parentId === input.parentId) return issue;

  const after = await issueRepo.setIssueParent(
    input.orgId,
    issue.id,
    input.parentId,
  );

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: ["parentId"],
  });

  return after;
}

export async function listSubIssues(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<readonly Issue[]> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  return issueRepo.listChildIssues(orgId, issue.id);
}

export async function getIssueRollup(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueRollup> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const tree = buildIssueTree(
    await issueRepo.listProjectIssues(orgId, issue.projectId),
  );
  const live = descendantsOf(tree, issue.id).filter((d) => d.archivedAt === null);
  const closed = live.filter((d) => isClosedStatus(d.status)).length;
  return { total: live.length, open: live.length - closed, closed };
}

/**
 * Called after a sub-issue stopped being open: when its direct parent has no
 * open issue left below it, the parent's assignee hears about it.
 */
async function notifyParentIfCompleted(
  actor: Actor,
  child: Issue,
): Promise<void> {
  if (child.parentId === null) return;

  const parent = await issueRepo.findIssueById(child.orgId, child.parentId);
  if (parent === null || parent.archivedAt !== null) return;
  if (parent.assigneeId === null) return;

  const tree = buildIssueTree(
    await issueRepo.listProjectIssues(child.orgId, parent.projectId),
  );
  const below = descendantsOf(tree, parent.id);
  if (below.length === 0) return;
  const stillOpen = below.some(
    (d) => d.archivedAt === null && !isClosedStatus(d.status),
  );
  if (stillOpen) return;

  await notify(child.orgId, "sub_issues_completed", [parent.assigneeId], {
    title: "All sub-issues are completed",
    body: `Every sub-issue of issue ${parent.id} is closed`,
    href: `/issues/${parent.id}`,
    actorId: actor.userId,
  });
}
